import{z as A,x as o,o as e,c as l,q as r,j as B,D as E,d as i,s as n,S as s}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"再平衡溢价","description":"","frontmatter":{"title":"再平衡溢价","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rebalancing-premium.md","filePath":"quant/rebalancing-premium.md","lastUpdated":1791413859000}'),p={name:"quant/rebalancing-premium.md"};function d(m,a,_,h,D,c){const t=o("Mermaid");return e(),l("div",null,[a[2]||(a[2]=r('<h1 id="再平衡溢价" tabindex="-1">再平衡溢价 <a class="header-anchor" href="#再平衡溢价" aria-label="Permalink to &quot;再平衡溢价&quot;">​</a></h1><div class="epigraph"><p>固定权重组合相对买入持有的超额，来自波动与相关，而不是来自有边的择时；它与多样性收益是同一枚硬币。</p><footer>—— 对照 Booth and Fama 对 diversification return 的讨论；Erb–Harvey 与再平衡的商品文献</footer></div><p><a href="/quant/leverage-volatility-drag">上一课</a>写每日重置的拖累。再平衡溢价（diversification return）的缺口是<strong>固定权重 vs 漂移权重</strong>：定期把权重拉回 \\(w\\)，等价于卖出相对强的、买入相对弱的。无预测时，这块超额的期望来自方差项，不是 alpha。本课收口多期单元，后面策略族不再把再平衡当「免费 alpha」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两资产、目标 50/50，波动高且相关低时，再平衡组合的几何收益可以高于各资产几何的加权，也常高于从不调仓的市值漂移组合。Booth–Fama 称之为 diversification return：\\(\\tfrac12\\sum w_i\\sigma_i^2-\\tfrac12\\sigma_p^2\\)。问题是把它写成<strong>会计恒等式+再平衡规则</strong>，而不是写成一个可卖的因子。费用、税、跳会把这块吃掉；相关升到 1 时溢价消失。</p><p><span class="marginnote">代一个数字进公式：两资产各 50%、年化波动都是 20%、相关为 0，则 \\(\\sigma_p^2 = 0.25\\times 0.04 + 0.25\\times 0.04 = 0.02\\)，即 \\(\\sigma_p\\approx 14.1\\%\\)。多样性收益 \\(\\approx \\tfrac12\\times 0.04 - \\tfrac12\\times 0.02 = 1\\%\\) 每年。若相关升到 1，\\(\\sigma_p\\) 变回 20%，这一项恰好归零——所以它是分散程度的会计影子，环境一变就没有，不是谁付给你的补偿。</span></p><p>与杠杆 ETF：杠杆 ETF 对<strong>单资产</strong>每日重置，震荡市拖累；多资产固定权重再平衡在资产间做均值回复式交易。符号取决于你是否在「卖出赢家」的那一侧，以及赢家是否继续赢（动量）。动量强时再平衡是负 alpha，溢价公式的期望仍可正但实现为负。</p>',7)),(e(),B(s,null,{default:E(()=>[n(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E4%B8%A4%E8%B5%84%E4%BA%A7%2050%2F50%20%E5%9B%BA%E5%AE%9A%E6%9D%83%E9%87%8D%22%5D%20--%3E%7C%22%E9%9C%87%E8%8D%A1%2C%20%E4%BD%8E%E7%9B%B8%E5%85%B3%22%7C%20B%5B%22%E5%8F%8D%E5%A4%8D%E5%8D%96%E6%B6%A8%E4%B9%B0%E8%B7%8C%22%5D%0A%20%20A%20--%3E%7C%22%E5%8D%95%E8%BE%B9%2C%20%E9%AB%98%E7%9B%B8%E5%85%B3%22%7C%20C%5B%22%E6%8C%81%E7%BB%AD%E5%8D%96%E5%87%BA%E8%B5%A2%E5%AE%B6%22%5D%0A%20%20B%20--%3E%20D%5B%22%E5%85%91%E7%8E%B0%E6%96%B9%E5%B7%AE%E5%B7%AE%3A%20%E6%BA%A2%E4%BB%B7%E4%B8%BA%E6%AD%A3%22%5D%0A%20%20C%20--%3E%20E%5B%22%E5%8A%A8%E9%87%8F%E5%BB%B6%E7%BB%AD%3A%20%E5%AE%9E%E7%8E%B0%E4%B8%BA%E8%B4%9F%22%5D%0A%20%20D%20--%3E%20F%7B%22%E6%89%A3%E9%99%A4%E8%B4%B9%E7%94%A8%E4%B8%8E%E7%A8%8E%E4%B9%8B%E5%90%8E%E8%BF%98%E5%89%A9%E5%90%97%3F%22%7D%0A%20%20E%20--%3E%20F%0A%20%20F%20--%3E%7C%22%E5%89%A9%E6%AD%A3%22%7C%20G%5B%22%E5%87%80%E6%BA%A2%E4%BB%B7%3A%20%E7%95%99%E5%9C%A8%E5%B7%A5%E7%A8%8B%E5%88%86%E8%A7%A3%E9%87%8C%22%5D%0A%20%20F%20--%3E%7C%22%E4%B8%8D%E5%89%A9%22%7C%20H%5B%22%E5%87%80%E5%80%BC%E4%B8%BA%E9%9B%B6%E6%88%96%E8%B4%9F%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">这张图回答的问题是「同一套规则,什么时候赚钱、什么时候赔钱」。关键分岔不是再平衡本身,而是行情形态:震荡低相关时你反复低买高卖;单边动量时同样的动作变成持续卖出赢家。所以评估再平衡溢价必须先给样本分段定性,全样本平均会把两种方向相反的效应轧平,得出一个毫无意义的年均值。</span></p><h3 id="不是对波动的风险溢价" tabindex="-1">不是对波动的风险溢价 <a class="header-anchor" href="#不是对波动的风险溢价" aria-label="Permalink to &quot;不是对波动的风险溢价&quot;">​</a></h3><p>波动风险溢价是卖出方差互换的补偿。再平衡溢价不要求有人付风险补偿，它是权重过程与二次变差的乘积。可以在风险中性世界里存在（作为不同财富过程的差）。不要用 <a href="/quant/variance-swap-vix">方差互换</a> 的价格去「解释」50/50 的超额。</p><p><span class="marginnote">商品趋势 vs 展期课已经把曲线收益与趋势分开。商品风险平价的再平衡溢价常被宣传夸大，要用 Erb–Harvey 的分解核对。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分解：组合几何 \\(\\approx\\) 加权几何 \\(+\\) 再平衡项 \\(+\\) 交叉项。用实际再平衡频率与费用模拟。对照买入持有（权重漂移）。若「溢价」只在无费用日频再平衡里出现，生产频率下可能为零。税务账户里再平衡溢价尤其贵，见税务课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>固定 \\(w\\) 强迫你在相对价格偏离时交易，捕获相对价格的负自相关（若存在）以及纯粹的方差差。数学上源自 \\(\\log\\sum w_i e^{x_i}\\) 的 Jensen。杠杆拖累源自 \\(\\log(1+\\lambda r)\\) 的 Jensen。都是凹/凸，比较对象不同。</p><p><span class="marginnote">Jensen 不等式翻译成白话：先平均再取对数，总是不小于先取对数再平均。固定权重等于定期把组合「重新平均」一次，于是把资产间方差差一点点兑现成几何收益；杠杆 ETF 是在单一资产上天天做同一件事，震荡里凹性反过来变成拖累。两件事数学同源（Jensen），但一个是资产间、一个是资产内，所以符号与量级都不能互相套用。</span></p>',9)),(e(),B(s,null,{default:E(()=>[n(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20FW%5B%22%E5%9B%BA%E5%AE%9A%E6%9D%83%E9%87%8D%E5%86%8D%E5%B9%B3%E8%A1%A1%22%5D%20--%3E%20Div%5B%22%E5%A4%9A%E6%A0%B7%E6%80%A7%E6%94%B6%E7%9B%8A%20%E6%96%B9%E5%B7%AE%E5%B7%AE%22%5D%0A%20%20Mom%5B%22%E5%8A%A8%E9%87%8F%E5%BB%B6%E7%BB%AD%22%5D%20--%3E%20Drag2%5B%22%E5%86%8D%E5%B9%B3%E8%A1%A1%E5%8F%AF%E8%83%BD%E8%B4%9F%20alpha%22%5D%0A%20%20Fee%5B%22%E8%B4%B9%E7%94%A8%E4%B8%8E%E7%A8%8E%22%5D%20--%3E%20Net%5B%22%E5%87%80%E6%BA%A2%E4%BB%B7%E5%8F%AF%E4%B8%BA%E9%9B%B6%22%5D%0A%20%20Div%20--%3E%20Net%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>权重若是风险平价，再平衡还对 vol 变化交易，多一层。估计 \\(\\Sigma\\) 时再平衡与估计噪声耦合。不要把再平衡溢价写进向客户承诺的 alpha；它应留在预期几何的工程分解里。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>再平衡溢价主要是多样性收益，不是择时 alpha。</li><li>与杠杆 ETF 拖累同属 Jensen，比较对象不同。</li><li>费用、税、动量可使其净值为负；不能当产品卖点。</li><li>出处：Booth and Fama, <em>Financial Analysts Journal</em>, 1992；Erb and Harvey 对商品再平衡的讨论。</li></ul>',4))])}const g=A(p,[["render",d]]);export{f as __pageData,g as default};
